```python
try:
    active = df[
        (df['row_kind'] != 'cancelled') &
        (df['row_kind'] != 'cancel') &
        (df['Currency'] == 'USD') &
        (df['Weight'] > 0) &
        (df['Weight UOM'].notna()) &
        (df['Weight UOM'] != '')
    ].copy()

    modes = active.groupby('Mode').agg(
        total_charge=('Total Charge', 'sum'),
        total_weight=('Weight', 'sum')
    ).reset_index()
    modes['cost_per_lb'] = modes['total_charge'] / modes['total_weight']
    modes_sorted = modes.sort_values('cost_per_lb', ascending=False).head(10)

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "ratio",
        "label": "cost_per_lb",
        "results": [
            {"name": str(row['Mode']), "value": round(float(row['cost_per_lb']), 6)}
            for _, row in modes_sorted.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "sum",
        "label": "total_freight_cost_usd",
        "results": [
            {"name": str(row['Mode']), "value": round(float(row['total_charge']), 4)}
            for _, row in modes_sorted.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight",
        "aggregation": "sum",
        "label": "total_weight_lb",
        "results": [
            {"name": str(row['Mode']), "value": round(float(row['total_weight']), 4)}
            for _, row in modes_sorted.iterrows()
        ]
    })

    result['assumptions'].append("cost_per_lb = sum(Total Charge) / sum(Weight) per Mode; cancelled and non-USD rows excluded; Weight > 0 and Weight UOM present required.")
    result['assumptions'].append("Weight UOM normalization applied upstream (889 rows unit-converted); sentinel nulls (5 rows) excluded via Weight > 0 filter.")

except Exception as e:
    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "ratio",
        "label": "cost_per_lb",
        "results": [{"name": "error", "value": 0.0}]
    })
